    }
  if$
}

FUNCTION {format.vol.num.pages}
{ volume field.or.null
  number empty$
  {
    issue empty$
    'skip$
    { "(" issue * ")" * * }
    if$
  }
  {
    "(" number * ")" * *
      volume empty$
	    { "there's a number but no volume in " cite$ * warning$ }
	    'skip$
      if$
  }
  if$
  pages empty$
  {
    eid empty$
    'skip$
	  {
      duplicate$ empty$
	    { pop$ format.pages }
	    { ":" * eid n.dashify * }
      if$
    }
    if$
  }
  {
    duplicate$ empty$
	  { pop$ format.pages }
	  { ":" * pages n.dashify * }
    if$
  }
  if$
}

